WITH parsed AS (SELECT id, created_at, ship_to, attributes['device'] AS device, ship_to.city AS ship_city, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts WHERE created_at >= '2023-10-01') SELECT ship_city, COUNT(*) FILTER (WHERE ship_city = 'Bangkok') AS bangkok_rows, COUNT(DISTINCT device) AS distinct_devices, SORT_ARRAY(COLLECT_SET(ship_city)) AS ship_city_list, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes_2, MAX(created_at) AS ended_at FROM parsed GROUP BY ship_city HAVING COUNT(*) FILTER (WHERE ship_city = 'Bangkok') >= 1
